-- GENERATED by tools/build_repo.py from tests/baselines/expected_kpis.json - do not edit by hand.
-- 02_kpi_baselines.sql : compares KPIs computed from dw.* with values computed independently (pandas) straight from the raw AdventureWorks files.
SET NOCOUNT ON;
CREATE TABLE #t (test_name nvarchar(200) NOT NULL, expected float NOT NULL, actual float NULL, tolerance float NOT NULL);
SELECT test_name, expected, actual, tolerance,
       CASE WHEN actual IS NOT NULL AND ABS(expected - actual) <= tolerance THEN N'PASS' ELSE N'FAIL' END AS status
FROM #t ORDER BY CASE WHEN actual IS NOT NULL AND ABS(expected - actual) <= tolerance THEN 1 ELSE 0 END, test_name;
DECLARE @fail int = (SELECT COUNT(*) FROM #t WHERE actual IS NULL OR ABS(expected - actual) > tolerance);
DECLARE @n int = (SELECT COUNT(*) FROM #t);
PRINT CONCAT(@n - @fail, ' of ', @n, ' KPI baseline tests passed');
IF @fail > 0
BEGIN
    THROW 52000, N'KPI baseline mismatch - see result set above.', 1;
END;
