INSERT INTO #t VALUES (N'sales: net sales (total)', 109846381.39988798, (SELECT SUM(net_sales_amount) FROM dw.fact_sales_line), 0.5);
INSERT INTO #t VALUES (N'sales: COGS (total)', 97288600.8008, (SELECT SUM(standard_cost_amount) FROM dw.fact_sales_line), 0.5);
INSERT INTO #t VALUES (N'sales: gross margin % (total)', 0.11432129524023438, (SELECT CAST(SUM(gross_margin_amount) AS float) / SUM(net_sales_amount) FROM dw.fact_sales_line), 1e-06);
INSERT INTO #t VALUES (N'sales: total billed (= SUM TotalDue)', 123216786.11590001, (SELECT SUM(net_sales_amount + allocated_freight_amount + allocated_tax_amount) FROM dw.fact_sales_line), 1.0);
INSERT INTO #t VALUES (N'sales: orders', 31465, (SELECT COUNT(DISTINCT sales_order_id) FROM dw.fact_sales_line), 0);
