INSERT INTO #t VALUES (N'time intel: YoY growth FY2025', 0.2858102968638021, (SELECT CAST(SUM(CASE WHEN d.fiscal_year = 2025 THEN f.net_sales_amount END) AS float) / SUM(CASE WHEN d.fiscal_year = 2024 THEN f.net_sales_amount END) - 1 FROM dw.fact_sales_line AS f JOIN dw.dim_date AS d ON d.date_key = f.order_date_key), 1e-06);
INSERT INTO #t VALUES (N'time intel: fiscal YTD at Dec-2024', 24978522.471642, (SELECT SUM(f.net_sales_amount) FROM dw.fact_sales_line AS f JOIN dw.dim_date AS d ON d.date_key = f.order_date_key WHERE f.order_date_key BETWEEN 20240701 AND 20241231), 0.5);
INSERT INTO #t VALUES (N'time intel: rolling 3M average at Jun-2025', 2392769.927446, (SELECT SUM(f.net_sales_amount) / 3.0 FROM dw.fact_sales_line AS f WHERE f.order_date_key BETWEEN 20250401 AND 20250630), 0.5);
INSERT INTO #t VALUES (N'finance: gross margin % FY2024', 0.08857744832272552, (SELECT CAST(SUM(f.gross_margin_amount) AS float) / SUM(f.net_sales_amount) FROM dw.fact_sales_line AS f JOIN dw.dim_date AS d ON d.date_key = f.order_date_key WHERE d.fiscal_year = 2024), 1e-06);
INSERT INTO #t VALUES (N'quota: quota FY2024', 36339000.0, (SELECT SUM(q.quota_amount) FROM dw.fact_sales_quota AS q JOIN dw.dim_date AS d ON d.date_key = q.quota_month_key WHERE d.fiscal_year = 2024), 0.5);
INSERT INTO #t VALUES (N'quota: attainment FY2024', 0.7929536243743637, (SELECT CAST(SUM(f.net_sales_amount) AS float) / (SELECT SUM(q.quota_amount) FROM dw.fact_sales_quota AS q JOIN dw.dim_date AS dq ON dq.date_key = q.quota_month_key WHERE dq.fiscal_year = 2024) FROM dw.fact_sales_line AS f JOIN dw.dim_date AS d ON d.date_key = f.order_date_key JOIN dw.dim_salesperson AS s ON s.salesperson_key = f.salesperson_key WHERE d.fiscal_year = 2024 AND s.quota_status = N'Quota-carrying'), 1e-06);
INSERT INTO #t VALUES (N'supply chain: purchase spend', 63791994.838, (SELECT SUM(line_total_amount) FROM dw.fact_purchase_line), 0.5);
INSERT INTO #t VALUES (N'supply chain: on-time delivery %', 0.999208592425099, (SELECT CAST(SUM(on_time_flag) AS float) / SUM(shipped_flag) FROM dw.fact_purchase_line), 1e-06);
INSERT INTO #t VALUES (N'supply chain: receipt fill rate %', 0.9909147305437154, (SELECT CAST(SUM(received_quantity) AS float) / SUM(order_quantity) FROM dw.fact_purchase_line), 1e-06);
INSERT INTO #t VALUES (N'supply chain: reject rate %', 0.03123792860307163, (SELECT CAST(SUM(rejected_quantity) AS float) / SUM(received_quantity) FROM dw.fact_purchase_line), 1e-06);
INSERT INTO #t VALUES (N'supply chain: inventory value', 20092679.1712, (SELECT SUM(inventory_value_amount) FROM dw.fact_inventory), 0.5);
INSERT INTO #t VALUES (N'supply chain: products below reorder point', 7, (SELECT COUNT(*) FROM (SELECT i.product_key FROM dw.fact_inventory AS i JOIN dw.dim_product AS p ON p.product_key = i.product_key GROUP BY i.product_key, p.reorder_point HAVING SUM(i.quantity) < p.reorder_point) AS x), 0);
